svg.script:
var ST="svgtl16",HN="http://www.w3.org/1999/xhtml";
var COLS=["#2ea043","#3fb950","#f0883e","#d47631","#f85149","#da3633","#58a6ff","#388bfd","#bc8cff","#a371f7","#e3b341","#d29922"];
var TYP={commit:{l:"Commit",c:"#26a641"},milestone:{l:"Jalon",c:"#f0883e"},release:{l:"Release",c:"#58a6ff"},bug:{l:"Bug",c:"#f85149"}};
var MOIS=["Jan","Fev","Mar","Avr","Mai","Jun","Jul","Aou","Sep","Oct","Nov","Dec"];
var S={projects:[],pinned:[]},FP=null,SC="#2ea043",INIT=false,DRAG_ID=null,DRAG_PIN_ID=null,EDIT_ID=null,TL_DESC=true;

function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function pad2(n){return n<10?"0"+n:String(n)}
    function getLocalDate(d){return d.getFullYear()+"-"+pad2(d.getMonth()+1)+"-"+pad2(d.getDate())}
    function td(){return getLocalDate(new Date())}
    function ago(n){var d=new Date();d.setDate(d.getDate()-n);return getLocalDate(d)}
    function fm(s){try{return new Date(s+"T12:00:00").toLocaleDateString("fr-FR",{day:"numeric",month:"short",year:"numeric"})}catch(e){return s}}
    function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}
    function $(i){return document.getElementById(i)}
    function err(m){var e=$("ERR");if(e){e.setAttribute("display","");e.textContent="ERR: "+m}}

    function load(){
    try{var r=localStorage.getItem(ST);if(r){S=JSON.parse(r);if(!S.pinned)S.pinned=[];return}}catch(e){}
    S={pinned:[],projects:[
    {id:uid(),name:"Refonte UI",desc:"Modernisation interface",color:"#2ea043",acts:[
    {id:uid(),date:ago(2),type:"commit",desc:"Grille responsive"},
    {id:uid(),date:ago(5),type:"commit",desc:"Design tokens CSS"},
    {id:uid(),date:ago(8),type:"milestone",desc:"Design system V2"},
    {id:uid(),date:ago(12),type:"commit",desc:"Composant modal"},
    {id:uid(),date:ago(15),type:"bug",desc:"Debordement menu"},
    {id:uid(),date:ago(22),type:"commit",desc:"Theme sombre"},
    {id:uid(),date:ago(30),type:"release",desc:"v2.0.0-beta"},
    {id:uid(),date:ago(45),type:"milestone",desc:"Maquettes validees"},
    {id:uid(),date:ago(55),type:"commit",desc:"Refactoring boutons"},
    {id:uid(),date:ago(68),type:"bug",desc:"Fix z-index"}
    ]},
    {id:uid(),name:"API REST",desc:"Backend RESTful",color:"#58a6ff",acts:[
    {id:uid(),date:ago(1),type:"commit",desc:"PUT /users/:id"},
    {id:uid(),date:ago(3),type:"bug",desc:"Validation email"},
    {id:uid(),date:ago(7),type:"commit",desc:"Auth JWT"},
    {id:uid(),date:ago(10),type:"commit",desc:"Schema BDD"},
    {id:uid(),date:ago(18),type:"milestone",desc:"API v1 prete"},
    {id:uid(),date:ago(25),type:"release",desc:"v1.0.0 prod"},
    {id:uid(),date:ago(32),type:"commit",desc:"Rate limiting"},
    {id:uid(),date:ago(50),type:"bug",desc:"Timeout pool"},
    {id:uid(),date:ago(62),type:"commit",desc:"Pagination"},
    {id:uid(),date:ago(75),type:"milestone",desc:"Architecture OK"}
    ]},
    {id:uid(),name:"Cloud",desc:"Migration AWS",color:"#f0883e",acts:[
    {id:uid(),date:ago(4),type:"commit",desc:"Terraform RDS"},
    {id:uid(),date:ago(9),type:"commit",desc:"CI/CD Actions"},
    {id:uid(),date:ago(14),type:"milestone",desc:"Staging OK"},
    {id:uid(),date:ago(20),type:"bug",desc:"Fuite Lambda"},
    {id:uid(),date:ago(28),type:"commit",desc:"CloudWatch"},
    {id:uid(),date:ago(38),type:"release",desc:"Migration auth"},
    {id:uid(),date:ago(48),type:"commit",desc:"Script PostgreSQL"},
    {id:uid(),date:ago(70),type:"milestone",desc:"Audit securite"}
    ]}
    ]};
    save();
    }
    function save(){try{localStorage.setItem(ST,JSON.stringify(S))}catch(e){}}

    function aP(n,d,c){S.projects.push({id:uid(),name:n.trim(),desc:d.trim(),color:c,acts:[]});save()}
    function uP(id,n,d,c){var p=fP(id);if(!p)return;p.name=n.trim();p.desc=d.trim();p.color=c;save()}
    function dP(id){S.projects=S.projects.filter(function(x){return x.id!==id});S.pinned=S.pinned.filter(function(x){return x!==id});if(FP===id)FP=null;if(EDIT_ID===id)EDIT_ID=null;save()}
    function aA(pid,t,dt,d){var p=fP(pid);if(!p)return;p.acts.push({id:uid(),type:t,date:dt,desc:d.trim()});save()}
    function dA(pid,aid){var p=fP(pid);if(!p)return;p.acts=p.acts.filter(function(a){return a.id!==aid});save()}
    function fP(id){return S.projects.find(function(x){return x.id===id})}
    function aC(){var c={};S.projects.forEach(function(p){p.acts.forEach(function(a){c[a.date]=(c[a.date]||0)+1})});return c}

    function lay(){
    var w=window.innerWidth||1400,h=window.innerHeight||900;
    var svg=document.documentElement;svg.setAttribute("width",w);svg.setAttribute("height",h);
    $("BG").setAttribute("width",w);$("BG").setAttribute("height",h);
    $("FO").setAttribute("width",w);$("FO").setAttribute("height",h);
    var a=$("A");if(a){a.style.width=w+"px";a.style.height=h+"px"}
    }

    /* ===== CSS ===== */
    function getCSS(){
    var r="";
    r+="*{box-sizing:border-box;margin:0;padding:0}";
    r+=".sb{width:280px;min-width:280px;background:#161b22;border-right:1px solid #30363d;padding:14px;overflow-y:auto;height:100%;perspective:1000px}";
    r+=".mn{flex:1;padding:16px;overflow-y:auto;height:100%;background:#0d1117}";
    r+=".inp{background:#0d1117;border:1px solid #30363d;color:#e6edf3;padding:6px 9px;border-radius:5px;font-family:inherit;font-size:13px;width:100%}";
    r+=".inp:focus{outline:none;border-color:#f0883e;box-shadow:0 0 0 2px rgba(240,136,62,.15)}";
    r+=".inp::placeholder{color:#484f58}select.inp{cursor:pointer}";
    r+=".ba{background:#f0883e;color:#fff;border:none;padding:7px;border-radius:5px;font-weight:600;cursor:pointer;font-family:inherit;font-size:13px;width:100%}.ba:hover{background:#d47631}";
    r+=".bg{background:0;color:#8b949e;border:1px solid #30363d;padding:2px 7px;border-radius:4px;cursor:pointer;font-family:inherit;font-size:11px}.bg:hover{border-color:#484f58;color:#e6edf3}";
    r+=".bd{background:0;color:#f85149;border:1px solid rgba(248,81,73,.3);padding:2px 7px;border-radius:4px;cursor:pointer;font-family:inherit;font-size:11px}.bd:hover{background:rgba(248,81,73,.1);border-color:#f85149}";
    r+=".pc{background:#1c2128;border:1px solid #30363d;border-radius:8px;margin-bottom:10px;transition:transform .3s, box-shadow .3s, border-color .3d;transform-style:preserve-3d;position:relative;cursor:grab}";
    r+=".pc:hover{border-color:#484f58;box-shadow:0 4px 12px rgba(0,0,0,.3);transform:translateY(-2px)}";
    r+=".pc.dragging{opacity:0.4;transform:scale(0.95);cursor:grabbing}";
    r+=".pc.drag-over{border-top:3px solid #f0883e;margin-top:-3px}";
    r+=".pc.spin{animation:spinY .6s ease-in-out}";
    r+="@keyframes spinY{0%{transform:rotateY(0)}50%{transform:rotateY(180deg)}100%{transform:rotateY(360deg)}}";
    r+=".pc-head{padding:10px 12px 6px;display:flex;align-items:center;gap:8px}";
    r+=".pc-body{padding:0 12px 10px}";
    r+=".pc-foot{padding:6px 12px;border-top:1px solid #30363d;display:flex;align-items:center;justify-content:space-between;background:#161b22;border-radius:0 0 8px 8px}";
    r+=".pri-badge{font-size:10px;font-weight:700;padding:2px 6px;border-radius:10px;background:#30363d;color:#8b949e;font-family:monospace}";
    r+=".handle{color:#484f58;cursor:grab;font-size:14px;user-select:none}.handle:hover{color:#8b949e}";
    r+=".tc{background:#161b22;border:1px solid #30363d;border-radius:7px;padding:8px 11px;height:100%;display:flex;flex-direction:column;gap:3px;justify-content:center}.tc:hover{border-color:#484f58}";
    r+=".sc{background:#161b22;border:1px solid #30363d;border-radius:7px;padding:10px;text-align:center}.sc:hover{border-color:#484f58}";
    r+=".fb{padding:3px 9px;border-radius:14px;font-size:11px;cursor:pointer;border:1px solid #30363d;background:0;color:#8b949e;font-family:inherit}.fb:hover{border-color:#484f58}.fb.on{background:#f0883e;border-color:#f0883e;color:#fff}";
    r+=".co{width:20px;height:20px;border-radius:50%;cursor:pointer;border:2px solid transparent;display:inline-block;vertical-align:middle}.co:hover{transform:scale(1.1)}.co.sel{border-color:#fff}";
    r+=".bdg{display:inline-flex;align-items:center;gap:3px;padding:1px 6px;border-radius:8px;font-size:10px;font-weight:600}";
    r+=".tst{background:#1c2128;border:1px solid #30363d;color:#e6edf3;padding:8px 12px;border-radius:6px;font-size:12px;max-width:280px;pointer-events:auto;animation:ti .3s ease-out both}";
    r+=".tst.rm{animation:to .2s ease-in both}";
    r+=".mo{position:absolute;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:opacity .2s;z-index:50}.mo.on{opacity:1;pointer-events:auto}";
    r+=".mb{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:16px;max-width:300px;width:85%}";
    r+="@keyframes ti{from{opacity:0;transform:translateX(40px)}to{opacity:1;transform:translateX(0)}}";
    r+="@keyframes to{from{opacity:1}to{opacity:0;transform:translateX(40px)}}";
    r+=".hm{transition:all .12s;cursor:pointer}.hm:hover{stroke:#8b949e;stroke-width:1.5}";
    r+=".pinc{background:#1c2128;border:1px solid #30363d;border-radius:8px;padding:14px;transition:border-color .2s, box-shadow .2s, opacity .2s, transform .2d;cursor:grab;position:relative}.pinc:hover{border-color:#484f58;box-shadow:0 6px 16px rgba(0,0,0,.3)}";
    r+=".pinc.dragging{opacity:0.3;transform:scale(0.95);cursor:grabbing}.pinc.drag-over{border:2px dashed #f0883e}";
    r+=".pinc-stat{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}";
    r+=".pinc-badge{font-size:10px;padding:3px 6px;border-radius:8px;background:#30363d;font-family:monospace}";
    r+=".pinc-last{margin-top:10px;font-size:11px;color:#484f58;border-top:1px solid #30363d;padding-top:8px}";
    return r;
    }

    /* ===== IMPORT / EXPORT ===== */
    function exportData(){
    try{
    var json=JSON.stringify(S,null,2);
    var blob=new Blob([json],{type:"application/json"});
    var url=URL.createObjectURL(blob);
    var a=document.createElementNS(HN,"a");
    a.href=url;a.download="project-timeline-backup.json";
    var wrap=$("A");if(wrap){wrap.appendChild(a);a.click();setTimeout(function(){wrap.removeChild(a);URL.revokeObjectURL(url)},100)}
    ts("Donnees exportees","s");
    }catch(e){ts("Erreur d export","e")}
    }
    function importData(){
    var inp=document.createElementNS(HN,"input");
    inp.type="file";inp.accept=".json";inp.style.display="none";
    inp.addEventListener("change",function(e){
    var file=e.target.files[0];if(!file)return;
    var reader=new FileReader();
    reader.onload=function(ev){
    try{
    var data=JSON.parse(ev.target.result);
    if(data && data.projects && Array.isArray(data.projects)){
    S=data;if(!S.pinned)S.pinned=[];
    save();FP=null;EDIT_ID=null;rA();
    ts("Donnees importees avec succes","s");
    }else{ts("Format de fichier invalide","e")}
    }catch(ex){ts("Erreur de lecture du fichier JSON","e")}
    };
    reader.readAsText(file);
    });
    var wrap=$("A");if(wrap){wrap.appendChild(inp);inp.click();setTimeout(function(){if(inp.parentNode)inp.parentNode.removeChild(inp)},2000)}
    }

    /* ===== SIDEBAR ===== */
    function rSB(){
    var sb=$("SB");if(!sb)return;
    var editProj=EDIT_ID?fP(EDIT_ID):null;if(editProj)SC=editProj.color;
    var pnVal=editProj?esc(editProj.name):"";var pdVal=editProj?esc(editProj.desc):"";var pbTxt=editProj?"Mettre a jour":"Creer le projet";
    var cp="";for(var i=0;i<COLS.length;i++){var c=COLS[i];cp+='<span class="co'+(c===SC?" sel":"")+'" style="background:'+c+'" data-c="'+c+'"></span>';}
        var pl="";
        for(var j=0;j<S.projects.length;j++){
            var p=S.projects[j];var priority=j+1;var actCount=p.acts.length;var isPinned=S.pinned.indexOf(p.id)!==-1;
            pl+='<div class="pc" draggable="true" data-id="'+p.id+'"><div class="pc-head"><span class="handle">&#9776;</span><span style="width:10px;height:10px;border-radius:50%;background:'+p.color+';flex-shrink:0"></span><span style="font-size:13px;font-weight:700;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(p.name)+'</span><span class="pri-badge">P'+priority+'</span></div><div class="pc-body">'+(p.desc?'<div style="font-size:11px;color:#8b949e;margin-bottom:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(p.desc)+'</div>':'')+'<div style="font-size:10px;color:#484f58"><span style="font-family:monospace">'+actCount+'</span> activite'+(actCount!==1?"s":"")+'</div></div><div class="pc-foot"><div style="display:flex;gap:4px"><button class="bg" data-ep="'+p.id+'">Edit</button><button class="bd" data-dp="'+p.id+'">Del</button></div><div style="display:flex;gap:2px">'+(j>0?'<button class="bg" data-mu="'+p.id+'">&#9650;</button>':'')+(j<S.projects.length-1?'<button class="bg" data-md="'+p.id+'">&#9660;</button>':'')+'<button class="bg" data-pp="'+p.id+'" style="'+(isPinned?"color:#f0883e;border-color:#f0883e":"")+'">&#128204;</button></div></div></div>';
                }
                var so='<option value="">Choisir un projet</option>';for(var k=0;k<S.projects.length;k++){var q=S.projects[k];so+='<option value="'+q.id+'">'+esc(q.name)+'</option>';}
                    sb.innerHTML='<div style="margin-bottom:16px"><div style="font-size:11px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">'+(editProj?"Modifier Projet":"Nouveau Projet")+'</div><form id="PF" style="display:flex;flex-direction:column;gap:7px"><input class="inp" id="PN" placeholder="Nom du projet" required="required" value="'+pnVal+'"/><input class="inp" id="PD" placeholder="Description" value="'+pdVal+'"/><div><div style="font-size:10px;color:#484f58;margin-bottom:3px">Couleur</div><div id="CP" style="display:flex;gap:4px;flex-wrap:wrap">'+cp+'</div></div><button type="submit" class="ba" id="PB">'+pbTxt+'</button>'+(editProj?'<button type="button" class="bd" id="CE" style="width:100%;margin-top:4px">Annuler</button>':'')+'</form></div><div style="margin-bottom:16px"><div style="font-size:11px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">Projets <span style="color:#484f58;font-weight:400">(Glisser)</span></div><div id="PL">'+(pl||'<div style="font-size:12px;color:#484f58;text-align:center;padding:8px">Aucun projet</div>')+'</div></div><div style="margin-bottom:16px"><div style="font-size:11px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">Ajouter Activite</div><form id="AF" style="display:flex;flex-direction:column;gap:7px"><select class="inp" id="AP" required="required">'+so+'</select><select class="inp" id="AT" required="required"><option value="">Type</option><option value="commit">Commit</option><option value="milestone">Jalon</option><option value="release">Release</option><option value="bug">Correction</option></select><input type="date" class="inp" id="AD" required="required"/><input class="inp" id="AX" placeholder="Description" required="required"/><button type="submit" class="ba">Ajouter</button></form></div><div><div style="font-size:11px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px">Donnees</div><div style="display:flex;gap:6px"><button class="ba" id="EXP" style="flex:1">Exporter</button><button class="ba" id="IMP" style="flex:1;background:#58a6ff">Importer</button></div></div>';
                    $("AD").value=td();
                    var cpEl=$("CP");if(cpEl){var spans=cpEl.querySelectorAll(".co");for(var x=0;x<spans.length;x++){(function(el){el.addEventListener("click",function(){SC=el.getAttribute("data-c");var all=cpEl.querySelectorAll(".co");for(var y=0;y<all.length;y++){all[y].classList.remove("sel")}el.classList.add("sel")})})(spans[x])}}
                            var pf=$("PF");if(pf){pf.addEventListener("submit",hPF)}var af=$("AF");if(af){af.addEventListener("submit",hAF)}var ce=$("CE");if(ce){ce.addEventListener("click",function(){EDIT_ID=null;SC="#2ea043";rSB()})}
                            var expBtn=$("EXP");if(expBtn){expBtn.addEventListener("click",exportData)}
                            var impBtn=$("IMP");if(impBtn){impBtn.addEventListener("click",importData)}
                            var eps=sb.querySelectorAll("[data-ep]");for(var i1=0;i1<eps.length;i1++){(function(b){b.addEventListener("click",function(ev){ev.stopPropagation();EDIT_ID=b.getAttribute("data-ep");rSB()})})(eps[i1])}
                                var dps=sb.querySelectorAll("[data-dp]");for(var i2=0;i2<dps.length;i2++){(function(b){b.addEventListener("click",function(ev){ev.stopPropagation();cDP(b.getAttribute("data-dp"))})})(dps[i2])}
                                    var mus=sb.querySelectorAll("[data-mu]");for(var i3=0;i3<mus.length;i3++){(function(b){b.addEventListener("click",function(ev){ev.stopPropagation();moveP(b.getAttribute("data-mu"),-1)})})(mus[i3])}
                                        var mds=sb.querySelectorAll("[data-md]");for(var i4=0;i4<mds.length;i4++){(function(b){b.addEventListener("click",function(ev){ev.stopPropagation();moveP(b.getAttribute("data-md"),1)})})(mds[i4])}
                                            var pps=sb.querySelectorAll("[data-pp]");for(var i5=0;i5<pps.length;i5++){(function(b){b.addEventListener("click",function(ev){ev.stopPropagation();pinP(b.getAttribute("data-pp"))})})(pps[i5])}
                                                var cards=sb.querySelectorAll(".pc");for(var c=0;c<cards.length;c++){(function(card){
                                                    card.addEventListener("dragstart",function(e){DRAG_ID=card.getAttribute("data-id");e.dataTransfer.effectAllowed="move";setTimeout(function(){card.classList.add("dragging")},0)});
                                                    card.addEventListener("dragend",function(){card.classList.remove("dragging");DRAG_ID=null;var all=sb.querySelectorAll(".pc");for(var i=0;i<all.length;i++){all[i].classList.remove("drag-over")}});
                                                        card.addEventListener("dragover",function(e){e.preventDefault();e.dataTransfer.dropEffect="move";if(DRAG_ID&&DRAG_ID!==card.getAttribute("data-id")){card.classList.add("drag-over")}});
                                                        card.addEventListener("dragleave",function(){card.classList.remove("drag-over")});
                                                        card.addEventListener("drop",function(e){e.preventDefault();card.classList.remove("drag-over");var targetId=card.getAttribute("data-id");if(!DRAG_ID||DRAG_ID===targetId)return;var dragIdx=-1,targetIdx=-1;for(var i=0;i<S.projects.length;i++){if(S.projects[i].id===DRAG_ID)dragIdx=i;if(S.projects[i].id===targetId)targetIdx=i}if(dragIdx===-1||targetIdx===-1)return;var dragItem=S.projects.splice(dragIdx,1)[0];S.projects.splice(targetIdx,0,dragItem);save();rSB();rFL();var droppedCard=document.querySelector('.pc[data-id="'+DRAG_ID+'"]');if(droppedCard){droppedCard.classList.add("spin");setTimeout(function(){droppedCard.classList.remove("spin")},700)}ts("Priorite mise a jour","s")});
                                                            })(cards[c])}
                                                            }

                                                            function moveP(id,dir){var idx=-1;for(var i=0;i<S.projects.length;i++){if(S.projects[i].id===id){idx=i;break}}if(idx===-1)return;var newIdx=idx+dir;if(newIdx<0||newIdx>=S.projects.length)return;var item=S.projects.splice(idx,1)[0];S.projects.splice(newIdx,0,item);save();rSB();rFL();var movedCard=document.querySelector('.pc[data-id="'+id+'"]');if(movedCard){movedCard.classList.add("spin");setTimeout(function(){movedCard.classList.remove("spin")},700)}ts("Priorite mise a jour","s")}
                                                                    function pinP(id){var idx=S.pinned.indexOf(id);if(idx===-1){S.pinned.push(id);ts("Projet epingle","s")}else{S.pinned.splice(idx,1);ts("Projet desepingle","i")}save();rA()}

                                                                    function hPF(e){e.preventDefault();var n=$("PN").value,d=$("PD").value;if(!n.trim())return;if(EDIT_ID){uP(EDIT_ID,n,d,SC);ts("Projet mis a jour","s")}else{aP(n,d,SC);ts("Projet cree","s")}EDIT_ID=null;SC="#2ea043";FP=null;rA()}
                                                                    function hAF(e){e.preventDefault();var p=$("AP").value,t=$("AT").value,d=$("AD").value,x=$("AX").value;if(!p||!t||!d||!x.trim())return;aA(p,t,d,x);ts("Activite ajoutee","s");FP=p;$("AF").reset();$("AD").value=td();rA()}
                                                                    function cDP(id){var p=fP(id);if(!p)return;shM("Supprimer","Supprimer "+p.name+" ?",function(){dP(id);ts("Supprime","e");rA()})}
                                                                    function cDA(pid,aid){shM("Supprimer","Supprimer cette activite ?",function(){dA(pid,aid);ts("Supprime","e");rA()})}

                                                                    /* ===== MAIN ===== */
                                                                    function rMN(){
                                                                    var mn=$("MN");if(!mn)return;
                                                                    if(FP && !fP(FP)) FP=null;
                                                                    var c=aC(),tP=S.projects.length,tA=0;
                                                                    for(var i=0;i<S.projects.length;i++){tA+=S.projects[i].acts.length}
                                                                        var sk=0,dd=new Date();dd.setHours(0,0,0,0);while(true){var k=getLocalDate(dd);if(c[k]&&c[k]>0){sk++;dd.setDate(dd.getDate()-1)}else break}

                                                                        var fh="";fh+='<button class="fb'+(!FP?" on":"")+'" data-f="">Tous</button>';
