                                                                                                                    function mc(c){var now=new Date(),ym=getLocalDate(now).substring(0,7),n=0;Object.keys(c).forEach(function(k){if(k.indexOf(ym)===0)n+=c[k]});return n}
                                                                                                                    function sC(l,v,c){return '<div class="sc"><div style="color:'+c+';font-size:12px;margin-bottom:2px">'+l+'</div><div style="font-size:18px;font-weight:700;font-family:monospace">'+v+'</div></div>'}

                                                                                                                    /* ===== HEATMAP ===== */
                                                                                                                    function rHM(){
                                                                                                                    var svg=$("HS");if(!svg)return;
                                                                                                                    var dateActs={};
                                                                                                                    for(var i=0;i<S.projects.length;i++){
                                                                                                                        var p=S.projects[i];
