                                                                                                                        for(var j=0;j<p.acts.length;j++){
                                                                                                                            var a=p.acts[j];
                                                                                                                            if(!dateActs[a.date]) dateActs[a.date]={count:0, projs:{}, lastDesc:""};
                                                                                                                            dateActs[a.date].count++;
                                                                                                                            dateActs[a.date].projs[p.id]=(dateActs[a.date].projs[p.id]||0)+1;
                                                                                                                            dateActs[a.date].lastDesc=a.desc;
                                                                                                                            }
                                                                                                                            }

                                                                                                                            var sz=10,gp=2,st=sz+gp,lm=30,tm=16;
                                                                                                                            var t=new Date();t.setHours(0,0,0,0);
                                                                                                                            var s=new Date(t);s.setDate(s.getDate()-364);
                                                                                                                            var sd=s.getDay(),mo=sd===0?6:sd-1;s.setDate(s.getDate()-mo);
                                                                                                                            var td2=Math.floor((t-s)/864e5)+1,nw=Math.ceil(td2/7);
                                                                                                                            var sw=lm+nw*st+4,sh=tm+7*st+4;
                                                                                                                            svg.setAttribute("width",sw);svg.setAttribute("height",sh);svg.setAttribute("viewBox","0 0 "+sw+" "+sh);

                                                                                                                            var h="";var jrs=["L","","M","","V","",""];
                                                                                                                            for(var i=0;i<7;i++){if(jrs[i])h+='<text x="1" y="'+(tm+i*st+sz-1)+'" fill="#484f58" font-size="8" font-family="sans-serif">'+jrs[i]+'</text>'}
                                                                                                                                var lmo=-1;
                                                                                                                                for(var w=0;w<nw;w++){var ws=new Date(s);ws.setDate(ws.getDate()+w*7);var mn=ws.getMonth();if(mn!==lmo){h+='<text x="'+(lm+w*st)+'" y="10" fill="#484f58" font-size="8" font-family="sans-serif">'+MOIS[mn]+'</text>';lmo=mn}}

                                                                                                                                    for(var w2=0;w2<nw;w2++){
                                                                                                                                        for(var d=0;d<7;d++){
                                                                                                                                            var cd=new Date(s);cd.setDate(cd.getDate()+w2*7+d);if(cd>t)continue;
                                                                                                                                            var ds=getLocalDate(cd);
                                                                                                                                            var data=dateActs[ds];
                                                                                                                                            var gx=lm+w2*st, gy=tm+d*st;

                                                                                                                                            if(data && data.count>0){
                                                                                                                                            h+='<g class="hm" data-d="'+ds+'">';
                                                                                                                                                if(FP){
