                                                                                                                                                            h+='<rect x="'+gx+'" y="'+curY+'" width="'+sz+'" height="'+pH+'" fill="'+proj2.color+'"/>';
                                                                                                                                                            curY+=pH;
                                                                                                                                                            }
                                                                                                                                                            }
