                                                                                                                                                                            }
                                                                                                                                                                            box.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" width="'+cw+'" height="'+th+'" viewBox="0 0 '+cw+" "+th+'" style="width:100%;overflow:visible">'+s+'</svg>';
                                                                                                                                                                            var btns=box.querySelectorAll("[data-da]");for(var b=0;b<btns.length;b++){(function(btn){btn.addEventListener("click",function(){var parts=btn.getAttribute("data-da").split("|");cDA(parts[0],parts[1])})})(btns[b])}
                                                                                                                                                                                }

                                                                                                                                                                                /* ===== TOAST ===== */
