                                                                                                                                                                                /* ===== MODAL ===== */
                                                                                                                                                                                function shM(ti,ms,cb){var mn=$("MN");if(!mn)return;var ov=document.createElementNS(HN,"div");ov.className="mo";ov.id="MO";var bx=document.createElementNS(HN,"div");bx.className="mb";var h3=document.createElementNS(HN,"h3");h3.style.cssText="font-size:14px;font-weight:700;margin-bottom:6px;color:#e6edf3";h3.textContent=ti;var p=document.createElementNS(HN,"p");p.style.cssText="font-size:12px;color:#8b949e;margin-bottom:14px";p.textContent=ms;var d=document.createElementNS(HN,"div");d.style.cssText="display:flex;gap:6px;justify-content:flex-end";var b1=document.createElementNS(HN,"button");b1.className="bg";b1.style.padding="4px 10px";b1.textContent="Annuler";b1.addEventListener("click",function(){ov.remove()});var b2=document.createElementNS(HN,"button");b2.className="bd";b2.style.padding="4px 10px";b2.textContent="Supprimer";b2.addEventListener("click",function(){if(cb)cb();ov.remove()});d.appendChild(b1);d.appendChild(b2);bx.appendChild(h3);bx.appendChild(p);bx.appendChild(d);ov.appendChild(bx);mn.appendChild(ov);setTimeout(function(){ov.classList.add("on")},10)}

